-- Check overlap between location equipment and water equipment
SELECT COUNT(*) FROM (
    SELECT l.loceqref FROM location l
    EXCEPT
    SELECT w.watereqref FROM waterandwaste w
) diff;

-- Check if they're exactly the same set
SELECT COUNT(*) FROM (
    SELECT l.loceqref FROM location l
    EXCEPT
    SELECT w.watereqref FROM waterandwaste w
) diff2;

SELECT COUNT(*) FROM (
    SELECT w.watereqref FROM waterandwaste w
    EXCEPT
    SELECT l.loceqref FROM location l
) diff3;

-- Check if there's a direct relationship between waterandwaste and operationmaintenance
SELECT COUNT(*) FROM (
    SELECT w.watereqref, om.opmainteqref 
    FROM waterandwaste w
    JOIN operationmaintenance om ON w.watereqref = om.opmainteqref
) x;

SELECT COUNT(*) FROM waterandwaste w 
WHERE CAST(w.waterlevelpercent AS numeric) / 100 * CAST(w.waterqualityindex AS numeric) / 100 * (1 - CAST(w.wastetanklevelpercent AS numeric) / 100) >= 0.5 
AND CAST(w.waterlevelpercent AS numeric) / 100 * CAST(w.waterqualityindex AS numeric) / 100 * (1 - CAST(w.wastetanklevelpercent AS numeric) / 100) < 0.7;
